# IPTVPremium: Correcao das tres tentativas independentes de abertura. Windows PowerShell 5.1 / PowerShell 7.
[CmdletBinding()]
param([string]$Projeto = (Get-Location).Path)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
function Get-BytesHash([byte[]]$Bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-', '') }
    finally { $sha.Dispose() }
}
function Get-TextHash([byte[]]$Bytes) {
    $text = [Text.Encoding]::UTF8.GetString($Bytes).TrimStart([char]0xFEFF).Replace("`r`n", "`n")
    return Get-BytesHash ([Text.Encoding]::UTF8.GetBytes($text))
}
$files = @(
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MovieOpeningPolicy.kt'; Binary = $false; MayCreate = $false; Versions = @(@{ Before = 'ADB131ED73A2AEFAEABF7CF347D102DA98F997DFB69E2A6475A9FCA3EE0F826D'; After = '29B38BF215E9AC9C0B0D6A242735661277A0579BB09403B43F998D02A7205847'; PayloadHash = '29B38BF215E9AC9C0B0D6A242735661277A0579BB09403B43F998D02A7205847'; Data = '' }; @{ Before = '7C34CC7D3A4C14DD578D94650C93FCAFF62AD41C07EF4E6CFEC2BBC1C648049A'; After = '29B38BF215E9AC9C0B0D6A242735661277A0579BB09403B43F998D02A7205847'; PayloadHash = '29B38BF215E9AC9C0B0D6A242735661277A0579BB09403B43F998D02A7205847'; Data = '' }) };
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/data/cache/CatalogDetailsWarmupCache.kt'; Binary = $false; MayCreate = $false; Versions = @(@{ Before = '0B22063378178A6E12CAD4B3D0A55361100A3699C4F004F9AD092B7E46D56950'; After = '8C018F25C7AB4C61A888E79D876F39699AB73CEEF2BCDA5D38A881FE463AA0C0'; PayloadHash = '8C018F25C7AB4C61A888E79D876F39699AB73CEEF2BCDA5D38A881FE463AA0C0'; Data = '' }) };
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MoviesViewModel.kt'; Binary = $false; MayCreate = $false; Versions = @(@{ Before = '67FB13D2143E0B04DC8CCAAA54F605EC71F2A14654688835495DB9DA01F17507'; After = '67FB13D2143E0B04DC8CCAAA54F605EC71F2A14654688835495DB9DA01F17507'; PayloadHash = '67FB13D2143E0B04DC8CCAAA54F605EC71F2A14654688835495DB9DA01F17507'; Data = '' }; @{ Before = '143CE1E703888D4E3BE9D60A41D4A89264A34715149FF82B2B7C1DE9AFCA6777'; After = '67FB13D2143E0B04DC8CCAAA54F605EC71F2A14654688835495DB9DA01F17507'; PayloadHash = '67FB13D2143E0B04DC8CCAAA54F605EC71F2A14654688835495DB9DA01F17507'; Data = '' }) };
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MovieDetailsScreen.kt'; Binary = $false; MayCreate = $false; Versions = @(@{ Before = '516718AAE280F1357166984E71E5CC6551650FBF8DC9D6E1C82115B26C116782'; After = '4430D8D85F4F2D27470EEE93F47FD2B29E239AEB8B39579FA33F24B5DC73BD75'; PayloadHash = '4430D8D85F4F2D27470EEE93F47FD2B29E239AEB8B39579FA33F24B5DC73BD75'; Data = '' }; @{ Before = '7C4E69409A3E9D213F551187752BCF9B801230A390B8BF03E525BB548A9AE6ED'; After = 'AED58760843A2209D7ABC62B4BF96E603AEEE3C9A6BA763117F42A3E02250A35'; PayloadHash = 'AED58760843A2209D7ABC62B4BF96E603AEEE3C9A6BA763117F42A3E02250A35'; Data = '' }; @{ Before = '51F88C9929B6FDA9FBA47FFD06D19BB4DF08839C067DD5219694C12694F84F65'; After = '51F88C9929B6FDA9FBA47FFD06D19BB4DF08839C067DD5219694C12694F84F65'; PayloadHash = '51F88C9929B6FDA9FBA47FFD06D19BB4DF08839C067DD5219694C12694F84F65'; Data = '' }; @{ Before = '14B1DA8D7CD9DE1B28144969470213BCCED1890F3B309DD65BAA028228D79904'; After = '14B1DA8D7CD9DE1B28144969470213BCCED1890F3B309DD65BAA028228D79904'; PayloadHash = '14B1DA8D7CD9DE1B28144969470213BCCED1890F3B309DD65BAA028228D79904'; Data = '' }) };
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/network/MovieOpeningAttempt.kt'; Binary = $false; MayCreate = $true; Versions = @(@{ Before = ''; After = '5E03A1EA12053735163D19C5713D0D1BCBFECBF8DF95382BB59872ED9597CDA0'; PayloadHash = '5E03A1EA12053735163D19C5713D0D1BCBFECBF8DF95382BB59872ED9597CDA0'; Data = '' }) }
)
$root = (Resolve-Path -LiteralPath $Projeto).Path
if (!(Test-Path -LiteralPath (Join-Path $root 'app/build.gradle.kts'))) {
    throw 'Abra o terminal na raiz de IPTVPremium (pasta com app e gradlew), ou informe -Projeto.'
}
# Verifica a versao de todos os arquivos antes de escrever qualquer mudanca.
$pending = @()
foreach ($file in $files) {
    $path = Join-Path $root $file.Path
    $present = Test-Path -LiteralPath $path -PathType Leaf
    $original = $null
    $version = $null
    if ($present) {
        $original = [IO.File]::ReadAllBytes($path)
        $current = if ($file.Binary) { Get-BytesHash $original } else { Get-TextHash $original }
        if (@($file.Versions | Where-Object { $_.After -eq $current }).Count -gt 0) { continue }
        $version = @($file.Versions | Where-Object { $_.Before -eq $current }) | Select-Object -First 1
        if ($null -eq $version) { throw "Arquivo diferente da base enviada: $($file.Path). Nada foi alterado." }
    } elseif (!$file.MayCreate) {
        throw "Arquivo necessario ausente: $($file.Path). Nada foi alterado."
    } else {
        $version = $file.Versions[0]
    }
    $packed = [IO.MemoryStream]::new([Convert]::FromBase64String($version.Data))
    $gzip = [IO.Compression.GZipStream]::new($packed, [IO.Compression.CompressionMode]::Decompress)
    $plain = [IO.MemoryStream]::new()
    try { $gzip.CopyTo($plain); $bytes = $plain.ToArray() }
    finally { $gzip.Dispose(); $plain.Dispose(); $packed.Dispose() }
    if ((Get-BytesHash $bytes) -ne $version.PayloadHash) { throw 'Pacote com integridade invalida. Nada foi alterado.' }
    $pending += @{ Path = $path; Relative = $file.Path; Bytes = $bytes; Original = $original; Present = $present; Hash = $version.PayloadHash }
}
if ($pending.Count -eq 0) {
    Write-Host 'Esta atualizacao ja esta aplicada.' -ForegroundColor Green
    return
}
$backup = Join-Path $root ('.navigation-backups/tentativas-filmes-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
[IO.Directory]::CreateDirectory($backup) | Out-Null
foreach ($file in $pending) {
    if ($file.Present) {
        $copy = Join-Path $backup $file.Relative
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($copy)) | Out-Null
        [IO.File]::Copy($file.Path, $copy, $false)
        if ((Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash -ne (Get-BytesHash $file.Original)) {
            throw 'Backup nao passou na verificacao. Nenhum arquivo do projeto foi alterado.'
        }
    }
}
@($pending | ForEach-Object { @{ path = $_.Relative; existed = $_.Present } }) |
    ConvertTo-Json | Set-Content -LiteralPath (Join-Path $backup 'manifest.json') -Encoding UTF8
try {
    foreach ($file in $pending) {
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($file.Path)) | Out-Null
        [IO.File]::WriteAllBytes($file.Path, $file.Bytes)
        if ((Get-FileHash -LiteralPath $file.Path -Algorithm SHA256).Hash -ne $file.Hash) { throw "Falha ao gravar $($file.Relative)." }
    }
} catch {
    foreach ($file in $pending) {
        if ($file.Present) { [IO.File]::WriteAllBytes($file.Path, $file.Original) }
        elseif (Test-Path -LiteralPath $file.Path -PathType Leaf) { [IO.File]::Delete($file.Path) }
    }
    throw
}
Write-Host 'Correcao aplicada: tentativas independentes em 5s, sem esperar conexao antiga ou consulta de fundo.' -ForegroundColor Green
Write-Host "Backup: $backup"
Write-Host 'Compile e execute pelo Android Studio para validar no seu aparelho.'
